import {escapeHtml as esc} from './report.js';
export const HELP_VERSION='10.0.0';
export const CALC_SECTIONS=[
 ['unidades91','Aplicação por grupo, tempos por unidade e área da cabina',`<p>A aplicação do edifício pertence a cada grupo. Demanda percentual e intervalo são calculados independentemente pelo uso selecionado. Os componentes populacionais mantêm suas áreas, quantidades e declarações; trocar o uso não apaga ambientes. Confira os componentes de cada pavimento atendido. Sobreposições entre grupos não são distribuídas automaticamente e as somas são somente informativas.</p><p>O seletor Critério de precisão foi retirado. Permanece a precisão integral de interpolação. No Avançado, paradas são derivadas dos pavimentos selecionados por grupo e por elevador, incluindo o acesso, sem edição direta. No Básico, o formulário recebe o número de paradas declarado.</p><p>Cada unidade informa aceleração, jerk, abertura, fechamento, entrada/saída por parada, tempo adicional de partida, pré-abertura e limite PPH. Unidades com tempos diferentes produzem resultados próprios dentro do contexto do grupo. NBR: T4 normativo = capacidade × tempo normativo por pessoa. FAB, com transferência por parada: T4 = paradas prováveis × tempo informado em s/parada. O tempo adicional de partida soma-se uma vez por ciclo FAB; não é tempo por passageiro. No modelo ISO personalizado, a parcela de transferência é (S+1) × tempo por parada e o tempo adicional de partida é tsd, aplicado no tempo de cada parada. A base ISO tabelada mantém 2 × Pcalc × tp. Essa diferença de bases fica identificada no relatório.</p><p>Dados antigos por pessoa são conservados. Na tela, a transferência aparece convertida para o equivalente por parada; até editá-la, continua a fórmula anterior. A conversão exata evita alterar resultados históricos apenas pela nova nomenclatura. Os valores digitados têm incrementos de 0,01 s, mas a precisão interna não é reduzida. Aceleração e jerk permanecem em passos de 0,05.</p><p>Preenchimento automático NBR: dividir igualmente entre abertura e fechamento a referência da porta; converter capacidade × tempo normativo por pessoa / paradas prováveis para s/parada, com sugestão arredondada a 0,01. Aceleração sugerida = min(1; max(0,30; 0,80 × velocidade)) m/s², jerk 1,20 até 2,50 m/s ou 1,60 acima, e partida adicional zero. São premissas editáveis do projeto, não dados reais do fornecedor nem prescrições de aceleração NBR. No ISO, o botão usa as tabelas disponíveis do documento de trabalho; fora dos nós publicados, requer dados personalizados. Confirme os valores com o fabricante.</p><p>A soma abertura + fechamento superior à referência da porta deixa ambos os campos vermelhos e alerta sobre performance. Na cabina existente, área = (frente/1.000) × (lado/1.000), com dimensões em mm. Compara-se com os limites inclusivos da tabela fornecida pelo usuário: abaixo do mínimo ou acima do máximo aparece em vermelho. De 4 a 20 passageiros, mantêm-se os limites da tabela. Para toda capacidade inteira C ≥ 21, área mínima = (C − 20) × 0,115 + 3,13 m². A área máxima de 21 a 33 usa as expressões fornecidas pelo usuário; acima de 33, área máxima = (C × 75 − 2.500) ÷ 100 × 0,16 + 5 m². As duas linhas especiais de 44 pessoas foram removidas; essa capacidade segue a fórmula geral. Os cálculos conservam a precisão integral, com arredondamento somente na exibição.</p>`],
 ['modulos90','Básico, Avançado e validação por condição',`<p>O Básico usa o mesmo núcleo NBR validado do Avançado, com precisão integral de interpolação. Cada coluna informa população própria, quantidade de elevadores, capacidade, paradas, percurso, velocidade, porta e abertura livre. Os tempos de fabricante, ISO, energia, escadas e medições não entram no Básico. T1 = 2D/v; T2 = N×ta/2; T3 = N×tp; T4 = capacidade×tempo por passageiro; total = T1+T2+T3+T4+0,1×(T3+T4). Intervalo = total/quantidade; capacidade em 5 min = 300×capacidade×quantidade/total. A população é declarada pelo responsável, com memória descritiva obrigatória.</p><p>Grupos são avaliados independentemente e não se somam capacidades para comprovar atendimento de populações coincidentes. O relatório divide tabelas extensas em até três colunas por página. O Básico adota exclusivamente a NBR; o Avançado conserva NBR e ISO em motores independentes. A opção ISO mantém a identificação e as limitações do documento fornecido, sem nova declaração de vigência.</p><p>Medições só são validadas no perfil real, usando os blocos ativos. Fretado e almoço do modelo legado só são exigidos quando esse modelo os utiliza. Consumo desativado não exige parâmetros energéticos; partidas diárias manuais só são validadas quando a base é manual. Rede de escadas desativada não bloqueia com parâmetros operacionais preservados. Quando a base de energia é PPH e a demanda não foi distribuída, a energia fica indisponível com explicação, sem substituição silenciosa por partidas manuais. A utilização média do pico continua necessária ao cálculo de energia por PPH, inclusive com expediente desativado.</p><p>Licença não altera fórmulas. Os bloqueios de acesso ficam no servidor, independentes de papéis, delegações e dados normativos. O cálculo salvo passa a ter uma cópia dos resultados, evitando recalcular ao abrir um projeto. Relatórios formatados são arquivados após o cálculo completo, com revisão e auditoria; o arquivo não executa scripts.</p>`],
 ['referencias88','Frente e lado de caixa/cabina e política de escadas',`<p>A segunda tabela complementa a referência de última altura e poço. Possui 660 configurações únicas, sem duplicatas após normalizar textos e números. Das 660 linhas, 42 apresentam inconsistências: 40 com mínimo superior ao máximo e duas com lado de cabina maior ou igual ao lado mínimo da caixa. Essas linhas e seus valores originais são conservados para conferência, mas não geram preenchimento automático.</p><p>Caixa/cabina são consultadas por capacidade, velocidade, percurso, casa de máquinas, tipo e abertura de porta, tipo de cabina, fabricação e entradas. A tabela contempla entradas frontais; portas de eixo vertical indicam consulta ao fornecedor. Não se interpolam valores. Se várias variantes forem compatíveis, escolha uma linha completa: medidas de variantes diferentes não são combinadas. Última altura e poço continuam sendo consultados na tabela anterior, com a prioridade dos dados reais por campo.</p><p>Na política atual de escadas, o atendimento depende dos parâmetros numéricos e da rede selecionada, sem os flags de confirmação operacional, dimensões/sentidos ou configuração técnica. O documento do fabricante não é obrigatório. Capacidade declarada de subida e descida continua necessária quando essa base é escolhida. Permanecem as verificações de caminho ao acesso, disponibilidade nos dois sentidos, largura compatível e capacidade por trecho. Resultados históricos conservam a política da versão em que foram calculados.</p>`],
 ['dimensoes87','Referência provisória de última altura e poço',`<p>A tabela do administrador possui 2.741 registros de entrada, 35 duplicados removidos e 2.706 configurações distintas. Capacidade em pessoas, velocidade em m/s, percurso máximo em m, alturas de porta/cabina em mm, casa de máquinas e fabricação identificam as opções. A consulta usa correspondência exata de capacidade, velocidade e alturas; o percurso deve ser menor ou igual ao máximo da linha. Não há interpolação nem extrapolação.</p><p>Oito configurações da base apresentam alternativas divergentes de última altura e poço. As alternativas são conservadas. Enquanto não houver dado real do fabricante, a referência adota o maior valor de cada dimensão entre as opções compatíveis, com aviso explícito. Essa combinação é um envelope provisório, não um produto confirmado. A tabela não fornece máximos admissíveis de instalação e não é um mínimo normativo universal.</p><p>Dados reais declarados pelo fornecedor têm prioridade por campo: a última altura real pode substituir a referência enquanto o poço ainda permanece provisório, e vice-versa. Registros de empresas diferentes são separados no catálogo. A autoria e a revisão são preservadas. As medidas existentes da edificação e medições em campo não recebem valores estimados automaticamente.</p><p>Exemplo da tabela: 8 pessoas, 1,00 m/s, percurso até 54 m, porta de 2.100 mm, cabina de 2.300 mm, sem casa de máquinas e fabricação padronizada: poço 1.100 mm; última altura 3.960 mm. Para 2,00 m/s, cabina de 2.400 mm e demais parâmetros compatíveis, há alternativas de 1.500/4.200 mm e 1.900/5.400 mm; a referência provisória adota 1.900/5.400 mm.</p>`],
 ['grupos86','Capacidade única e cálculo independente dos grupos',`<p>A capacidade em pessoas de cada coluna é a única entrada de lotação do elevador. Os cálculos de paradas prováveis, capacidade de transporte, partidas e perfis usam essa capacidade. No ISO, aplica-se também o fator de ocupação FC registrado no grupo, sem reaproveitar fórmulas NBR.</p><p>Massa estimada na cabina = capacidade em pessoas × massa adotada por pessoa. Cada elevador possui sua própria seleção de kg/pessoa (75 por padrão para compatibilidade; editável). Este resultado não é a carga nominal de placa nem uma verificação normativa de carga/área. Velocidade em m/min = velocidade em m/s × 60.</p><p>Cada grupo usa os seus elevadores e a população dos pavimentos que atende. Grupos com cobertura coincidente avaliam a mesma demanda independentemente; não se somam os resultados para afirmar atendimento. Equipamentos com configurações diferentes são calculados em lotes dentro do grupo; destinos distintos conservam as verificações de zoneamento. Medições globais permanecem na visão consolidada informativa e não são distribuídas automaticamente: os perfis dos grupos são estimados quando não há medições segregadas.</p><p>O percurso de referência é (paradas − 1) × 2,80 m. Para 11 paradas: 10 × 2,80 m = 28,00 m. É uma premissa de projeto informada pelo usuário; confirme as distâncias reais entre pavimentos. Não é apresentado como mínimo universal normativo.</p>`],
 ['caminho851','Seleção do caminho das escadas e vínculo com o acesso',`<p>A marcação automática percorre os índices físicos do acesso principal ao pavimento escolhido, incluindo os dois extremos. Não usa o valor numérico da etiqueta nem altera as marcações. Uma remoção manual modifica somente o pavimento solicitado. Os trechos continuam sujeitos às verificações de sentidos, capacidades e ligação física existentes.</p><p>Nas seleções novas, o flag do acesso integra a confirmação de continuidade. Se estiver desmarcado, não há abatimento populacional por essa rede, mesmo que as capacidades dos trechos isolados sejam suficientes. Selecionar o caminho não comprova capacidade operacional: a revisão e o recálculo continuam obrigatórios. Não se introduziu um novo limite numérico normativo.</p>`],
 ['equipamentos85','Dados individuais, geometria e configurações condicionais',`<p>Capacidade, velocidade, abertura livre e tipo de porta podem variar por elevador. Cada equipamento usa as paradas selecionadas e o percurso entre as elevações dos extremos atendidos. Para o cálculo, equipamentos idênticos e com os mesmos destinos podem ser reunidos; os demais permanecem separados. Mantêm-se população, capacidade, intervalo, partidas, energia e gráficos coerentes com esses dados no motor NBR ou no modelo ISO escolhido.</p><p>A aplicação mantém os critérios de zoneamento existentes. Destinos independentes têm população e resultados próprios. Uma sobreposição de demanda não é resolvida atribuindo toda a população a todos os equipamentos: exige distribuição específica. O método de mínimo mantém as características e proporções informadas, sem otimização automática de despacho.</p><p>O cadastro de esteiras usa dados declarados do fabricante e não introduz regra normativa de exclusão populacional. A matriz de escadas identifica descontinuidades e alimenta o estudo existente, conservando condições de capacidade e confirmação. Não há novos limites normativos inventados nesta atualização.</p>`],
 ['populacao84','População registrada e atendimento parcial das escadas',`<p>A população calculada de cada ambiente permanece visível antes das exclusões de participação, uso, acesso ou escadas. O total registrado é o maior entre calculada e declarada por ambiente. A exclusão não apaga esse registro: somente a parcela que entra nos elevadores é reduzida. O resumo mostra calculada, declarada, não computada, parcela por escadas e saldo para os elevadores; os motivos constam do relatório e PowerPoint.</p><p>Exemplo: 160 pessoas e escadas que atendem 100 pessoas equivalentes deixam 60 nos elevadores. Sem caminho contínuo ao principal, configuração técnica válida ou confirmação operacional, não se desconta nenhuma pessoa. Atendimento integral pode excluir toda a parcela solicitada, conforme as condições de NBR 5665, 5.1.6, ou documento ISO informado, 4.3.3.4. A regra proporcional para atendimento parcial é uma premissa de projeto solicitada pelo responsável, sem atribuição a esses itens.</p><p>Por trecho, C = menor capacidade de subida/descida × janela/60 × utilização/100. Capacidade equivalente de população = C ÷ (demanda percentual/100). Distribuir proporcionalmente entre os andares dependentes, sem ultrapassar nenhum trecho compartilhado. Quando um gargalo local esgota sua capacidade, a capacidade restante dos demais trechos pode atender os outros andares. Todos os ambientes da rede considerados na análise reservam capacidade; somente os que solicitam atendimento por escadas recebem abatimento. O saldo de cada estudo é arredondado para cima. Os valores intermediários podem ser fracionários.</p><p>O nome da composição é automático: Andar 01 a Andar 09 para dígitos de 1 a 9; Andar 00 para zero, Andar -01 para -1 e Andar S1 para marcação com letras. A marcação física continua 1, 0, -1, S1 etc. A indicação do ambiente permanece editável e não é substituída. Ambientes distintos do mesmo andar compartilham o nome de andar e mantêm suas posições e identificações próprias.</p>`],

 ['destino82','Antecipador: lotação, agrupamento e limites do método',`<p>Cálculo complementar exclusivo da proposta do fornecedor. P = Q × ocupação/100; o padrão de 80% é premissa editável, não limite normativo. A metodologia genérica adapta o agrupamento por destinos de Al-Sharif e Peters (2018), §§1 e 3, ao cenário de entrada no acesso: gerar destinos por distribuição populacional; ordenar e agrupar passageiros; calcular viagens e repetir lotes com semente reproduzível. Quantidades inteiras amostradas próximas de P definem as rotas, com mínimo de uma pessoa por rota. P permanece a lotação média equivalente, inclusive quando inferior a uma pessoa.</p><p>Por rota: T = soma dos tempos cinemáticos de cada deslocamento + (S+1) × (abertura + fechamento − pré-abertura + permanência) + 2P × tempo de transferência + adicional de ciclo. S exclui o acesso; o retorno vazio está incluído. Não é a equação da NBR nem recebe automaticamente seu adicional de 10%. Na tabela física, distâncias e probabilidades usam os pavimentos atendidos e sua população principal adotada. Sem distribuição por andar, adota-se uniformidade, explicitada na memória.</p><p>Capacidade = 300 × P × quantidade / RTT médio; intervalo de um grupo homogêneo = RTT / quantidade. Grupos compatíveis compartilham demanda proporcional às capacidades; com tempos diferentes, intervalo agregado = 1 / soma(quantidade/RTT). As zonas permanecem independentes. Partidas necessárias por elevador = demanda horária alocada / P × (S+1) / quantidade. Máximo pelo tempo = 3.600 × (S+1) / RTT, limitado também pelo PPH informado pelo fabricante.</p><p>A amostragem padrão/refinada solicita até 1.024/4.096 lotes, limitada pelo porte do grupo. Registram-se lotes efetivos, semente e erro padrão do RTT. Esse erro mede variabilidade amostral, sem cobrir as hipóteses do modelo. O convencional comparativo usa os mesmos destinos amostrados e a mesma ocupação, sem agrupar destinos; nenhuma melhoria percentual é imposta por marca.</p><p>No método documentado, RTT, S e distância média são declarações do fornecedor para a mesma configuração e ocupação. A documentação e a confirmação são obrigatórias; os valores não são convertidos em certificação pelo programa. No consumo de uma proposta de zona única, a média dos tempos cinemáticos por partida do cenário alimenta a estimativa, em lugar de recalcular o tempo apenas pela distância média. Não extrapolar uma melhoria no pico de entrada para almoço ou saída. No caso de antecipador em múltiplas zonas, o consumo consolidado fica pendente de estudo energético por zona.</p><p>Al-Sharif e Peters (2018): <a href="https://joomla.peters-research.com/index.php/support/articles-and-papers/250-using-the-monte-carlo-simulation-to-evaluate-the-round-trip-time-under-destination-group-control">agrupamento e cálculo Monte Carlo</a>. So e Al-Sharif (2019): <a href="https://nectar.northampton.ac.uk/id/eprint/12587/1/So_Albert_Al_Sharif_Lutfi_ELS_2019_Calculation_of_the_elevator_round_trip_time_under_destination_group_control_using_offline_batch_allocations_and_real_time_allocations.pdf">diferenças entre lotes prévios e alocações em tempo real</a>. A ISO 8100-32:2020, 5.3 e seção 8, requer simulação para controle de destino: este módulo preliminar não substitui essa validação, não declara conformidade e não altera o documento N69 informado na opção ISO.</p>`],
 ['fornecedores','Propostas, classificação e energia por fornecedor',`<p>O responsável salva e calcula o estudo-base. Em Projetos e ferramentas → Fornecedores e contratante, cadastra empresa, contato e email de acesso. Cada fornecedor vê o estudo-base e somente sua proposta. O contratante autorizado vê as propostas e a classificação. As informações do fabricante não reescrevem a população ou a geometria definida pelo responsável.</p><p>A ordenação coloca pendências técnicas no fim, depois verifica atendimento de tráfego e PPH e, em seguida, menor consumo estimado. Não considera automaticamente preço, manutenção, qualidade ou aprovação de contratação. Cabo com D/d menor que 40 gera pendência pelo critério padrão da NBR 16858-1 consultada, 5.5.2.1. Cintas e meios alternativos exigem comprovação específica, sem aplicar 40d automaticamente.</p><p>A proposta informa potência nominal e potência elétrica média da máquina, correntes/tensões de controle e sinalização, tecnologia, suspensão, cabos, polia e recuperação. Na ausência de potência, a referência estimada usa 75 kg/pessoa, desequilíbrio de 50% da carga nominal e rendimento global de 75%: P mecânica = 0,5 × capacidade × 75 × 9,80665 × velocidade / 1000; P elétrica = P mecânica / 0,75. Corrente ausente usa 0,25 A em cada circuito. Essas são hipóteses editáveis, sem dimensionamento da máquina. Controle e sinalização são considerados contínuos no expediente, incluindo movimento e espera.</p><p>Partidas diárias por elevador = PPH necessário calculado × horas do expediente × utilização média do pico declarada. Inicialmente 20% é uma hipótese para exploração, sem garantia de representar o edifício. Partidas medidas e ensaio energético são melhorias recomendadas. Nas opções de partidas declaradas, usa-se o número diário fornecido. O consumo fora do expediente não foi modelado.</p><p>Mostram-se equipamento existente e produto proposto, sem gráfico separado de redução. O contratante pode anexar a conta de energia e conferir kWh, custo variável de energia e total. Tarifa de referência = custo variável / kWh. O responsável aplica essa tarifa e recalcula o estudo. Economia anual estimada = (consumo anual existente − proposto) × tarifa variável. Outros usos do imóvel e custos fixos não são tratados como economia dos elevadores.</p><p>O catálogo é separado por empresa do convite, modelo, velocidade e capacidade. Ao mudar velocidade/capacidade/modelo, o fornecedor recebe os últimos dados cadastrados. Alterações diferentes mostram a autoria anterior e exigem confirmação de substituição, com revisão contra concorrência.</p>`],
 ['pavimentos-zonas','Geometria dos pavimentos e resultados por zona',`<p>Elevação de cada linha = soma das distâncias desde a base inferior. Para cada grupo: paradas = quantidade de linhas atendidas; percurso = elevação do destino superior − elevação do inferior atendido. Andares intermediários contribuem para a distância mesmo sem parada. Distâncias de descontos e desníveis das escadas seguem essa geometria quando ativa.</p><p>Grupos com destinos idênticos compartilham a população da zona. Para destinos diferentes, a zona adota somente os ambientes dos seus pavimentos e aplica o mesmo motor selecionado, sem misturar fórmulas NBR e ISO. População atendida por zonas diferentes não é duplicada: a sobreposição exige definição de distribuição em estudos próprios. Mínimo, capacidade, intervalo, perfis e partidas são avaliados por zona. Capacidade total é informativa e não conclui atendimento de zonas insuficientes.</p><p>As equações ISO parametrizadas utilizam distância uniforme entre destinos servidos. Diferenças são bloqueadas em vez de usar uma média com aparência de validação. Medições globais do acesso não identificam o destino por zona e não são copiadas como medições segregadas; as zonas usam perfis estimados, com aviso. O consumo mantém as partidas necessárias de cada grupo e a mesma fronteira temporal declarada.</p><p>Em edifícios comerciais de escritórios, o desconto de 50% pode alcançar os dois pavimentos adjacentes ao acesso: imediatamente acima e imediatamente abaixo, até 5 m. Contam-se pavimentos distintos, permitindo compartilhar a condição entre ambientes do mesmo andar. Nos demais usos permanece o critério anterior de um andar.</p>`],
 ['entrada8','Dependências e preenchimento dos cálculos',`<p>Paradas prováveis NBR dependem da lotação e do número de paradas incluindo acesso. No modelo ISO, dependem também do fator de ocupação. O painel permite essa conferência parcial mesmo quando velocidade ou tempos ainda não foram informados. Não apresenta um ciclo completo como válido apenas por S/N estarem disponíveis.</p><p>Capacidade e intervalo exigem quantidade, percurso, velocidade, lotação, portas e tempos aplicáveis. Movimento e partidas precisam de aceleração, jerk e tempos do fabricante ou base ISO indicada. População depende das entradas e decisões de cada ambiente. Energia depende das partidas, horas/dias e premissas elétricas. Campos faltantes ficam laranja e a lista de pendências identifica a etapa correspondente. Rascunho não é resultado calculado.</p><p>Componentes complementares podem ser incluídos, separados ou excluídos por decisão registrada. A inclusão no principal usa seu critério de demanda, identificada como uso composto escolhido pelo gestor. Não transforma automaticamente essa escolha em uma exigência normativa. Declarações e descontos continuam aplicados por ambiente, sem duplicar populações.</p>`],
 ['dimensoes','Dimensões declaradas e capacidade das escadas por quantidade',`<p>O comparativo dimensional usa as faixas mínima/máxima fornecidas para caixa, última altura e poço. No retrofit, compara essas faixas com as medições independentes do fornecedor e registra diferenças em relação às medidas do gestor. Consistência básica de cabina/porta e identificação dos acessos também é verificada. Não há fórmula universal implementada que derive todas as dimensões pela velocidade ou abertura da porta.</p><p>Na rede com múltiplas escadas, capacidade horária de subida = soma(capacidade unitária de subida × quantidade similar em serviço); repetir para descida. Capacidade na janela = capacidade horária × minutos/60 × utilização/100. Demanda = soma das populações dependentes × percentual da janela. Todos os trechos do caminho precisam atender nos dois sentidos. Interrupção mantém toda a população dependente nos elevadores. Capacidade insuficiente permite atendimento parcial apenas pela premissa de projeto descrita em População registrada e atendimento parcial.</p>`],
 ['expediente','Expediente, medições e pré-abertura',`<p>Em Parâmetros, informe início/fim do expediente e almoço, em horários múltiplos de cinco minutos, no mesmo dia. Perfis estimados são redistribuídos conservando o total de pessoas. Contagens medidas preservam os blocos e os horários reais; uma janela fora do expediente exige corrigir os horários, sem esticar a medição.</p><p>Na NBR, a abertura antecipada é uma premissa FAB: T3 FAB = N × (abertura + fechamento − pré-abertura), e o adicional de 10% acompanha o tempo adotado. Não altera a tabela nem o cálculo NBR. No ISO, tpre reduz o tempo de desempenho do modelo informado. Pré-abertura maior que abertura é recusada. A curva ideal também exige que a sobreposição caiba no movimento.</p><p>A soma abertura+fechamento acima da tabela 3 NBR gera aviso com a referência e o risco de perda de performance. Não é um limite universal de segurança. PPH FAB zero indica dado ausente em amarelo. Limite inferior ao PPH necessário é vermelho e informa não atendimento. PPH NBR/FAB do quadro = 3600 × paradas/partidas prováveis / tempo de ciclo; a linha total soma os grupos pela quantidade. O máximo operacional considera distância média e limite do fabricante em memória própria.</p>`],

 ['tracao','Polia, suspensão e potência do fornecedor',`<p>Em Gráficos de performance e economias, Energia e potência, abra Configurar estimativa de consumo e Dados do fornecedor por grupo e a tecnologia desejada. Ative Usar dados próprios do fornecedor e informe fornecedor, máquina/acionamento e documento técnico com revisão. O cadastro é independente por grupo, tecnologia e modelo NBR/ISO; estudos externos têm seus próprios conjuntos.</p><p>Informe cabos de aço ou cintas e o diâmetro primitivo real da polia, em mm. A lista inclui 150 mm, que é uma opção de equipamento específico e não uma regra geral de cintas. Para cabos, os diâmetros 4 mm, 6 mm, 3/8 pol. (9,525 mm), 1/2 pol. (12,700 mm) e 5/8 pol. (15,875 mm) têm referências 40d de 160, 240, 381, 508 e 635 mm. Outro diâmetro pode ser digitado.</p><p>A ABNT NBR 16858-1:2021 consultada, 5.5.2.1, define a relação mínima D/d de 40 para cabos de aço. O item 5.5.1.2 a) adota diâmetro nominal padrão mínimo de 8 mm. Cintas e cabos com características alternativas requerem comprovação conforme 5.5.1.1. Registrar o documento da aplicação alternativa. O programa sinaliza essas condições sem emitir certificação, e exige confirmar a edição aplicável ao projeto.</p><p>Informe relação de suspensão r:1 (1, 2, 4 ou outro valor) e redução motor/polia (1 sem redutor). Em velocidade nominal v: n da polia = 60×v×r/(π×D em metros); n do motor = n da polia×redução. Torque nominal estimado = 60000×P2/(2π×n motor). São indicadores geométricos, sem dimensionamento de motor, freio, tração ou aceleração. O diâmetro muda rotação e torque; sozinho não estabelece economia.</p><p>Cadastre a potência nominal mecânica P2 de cada motor, incluindo a opção regenerativa. Para consumo, prefira a potência média elétrica documentada do conjunto: ela substitui o valor comum apenas naquele grupo/tecnologia. Alternativamente, use a estimativa P elétrica = P2×fator mecânico médio/(rendimento motor×rendimento acionamento), com percentuais convertidos a frações. O fator representa o ciclo informado pelo fornecedor e não a ocupação da cabina. Dados incompletos impedem cálculo atualizado.</p><p>O percentual retornado próprio, se preenchido, substitui o comum; vazio herda o da tecnologia. Potência já líquida exige retorno zero; estimativa pelo motor utiliza base bruta. Os parâmetros comuns de espera, tempo e auxiliares permanecem. O gráfico de potência nominal de cada grupo mostra somente dados do fornecedor, da maior para a menor potência P2 em kW por elevador. O gráfico de consumo é ordenado do maior para o menor kWh/ano; a redução fica em valores numéricos da memória, sem gráfico separado. Empates preservam a ordem original. Dados ausentes não aparecem como zero. A redução da potência nominal no quadro regenerativo × referência é independente da redução de kWh: regenerar não exige automaticamente um motor menor. Gráficos e memória recalculados entram no relatório e PowerPoint editável.</p>`],
 ['curvas','Curvas de viagem e percurso médio',`<p>Cada grupo possui três painéis: viagem direta entre extremos, andares consecutivos e percurso médio considerando as paradas prováveis e o retorno ao acesso. Entre andares, a distância é D/(p−1). No percurso médio NBR, a distância é 2D/N, sendo N as paradas prováveis do ciclo. No ISO, é 2Hdf/(S+1).</p><p>A curva velocidade×tempo integra sete fases limitadas por jerk, aceleração e distância. O gráfico informa a velocidade efetivamente atingida. As marcações de distância são acumuladas pela integração, sem supor movimento uniforme. É um perfil ideal; nivelamento específico na zona de porta depende de dados do fabricante.</p><p>Nos painéis diretos, a transferência utiliza a lotação adotada: c×tempo de entrada/saída na NBR e 2Pcalc×tempo por sentido no ISO. No percurso médio, essa transferência é rateada pelas partidas/paradas prováveis. Na NBR, inclui-se adicional de 10% sobre portas e transferência, partida de ciclo/N e permanência operacional. No ISO, usam-se atrasos e pré-abertura do modelo, sem adicionar regras NBR.</p><p>O tempo ideal na distância média é um indicador complementar e pode diferir do RTT/(S+1) no ISO. PPH de cada percurso = 3600/tempo completo, limitado pelo fabricante quando informado. Não substitui o ciclo de tráfego, a demanda da população ou o limite térmico. A prévia usa a velocidade, os tempos e os pavimentos atendidos de cada elevador do grupo. Unidades com parâmetros diferentes têm curvas separadas. A velocidade nominal indicada acompanha o cadastro; em viagens curtas, a velocidade atingida pode ser menor devido à aceleração e ao jerk. A prévia acompanha as entradas; relatório e apresentação exigem cálculo completo atualizado.</p>`],
 ['performance','Performance de atendimento e medição por cinco minutos',`<p>Escolha tráfego leve, moderado ou modelo real conforme contagens no pavimento principal. A tabela enviada pelo proprietário fornece entrada, almoço entrada, almoço saída e saída em 12 blocos. Sua unidade não aparece na imagem: o programa oferece percentual da população por bloco ou pessoas estimadas e registra a escolha. Não normaliza os perfis novos para 80%.</p><p>Perfis anteriores preservam os percentuais e pesos normalizados do estudo legado, com fretado e almoço próprios. Essas opções não alteram a tabela enviada nem medições reais.</p><p>No modo real, informe data, responsável, horários e contagens absolutas inteiras, inclusive zero. Vazio bloqueia o cálculo completo. A janela pode ter até 288 blocos; reduzir a janela preserva valores além da parte ativa. Também é possível colar CSV com as quatro colunas entrada;almoco_entrada;almoco_saida;saida. Contagens não substituem a população adotada.</p><p>A capacidade é obtida do ciclo do modelo escolhido, com permanência adicional operacional. Entrada, almoço e saída representam períodos diferentes; no almoço, os dois sentidos compartilham a mesma oferta, proporcionalmente à demanda acumulada. Fila seguinte = demanda acumulada − pessoas atendidas. Os resultados incluem quatro gráficos e memória por bloco.</p><p>É uma aproximação com capacidade de pico, sem despacho individual, tempo médio real de espera ou simulação normativa de duas horas. Picos medidos podem superar a capacidade mesmo quando o dimensionamento populacional atende. Medições do estudo principal não são copiadas como medições de usos externos separados.</p>`],
 ['energia','Consumo elétrico e comparação de tecnologias',`<p>Comparar VVVF não regenerativo, VVVF regenerativo, AC2, CC com motor-gerador e CC com conversor estático. Os valores iniciais são exemplos ilustrativos, não coeficientes típicos ou garantias de economia. Preencha potência média elétrica de movimento, W em espera, abatimento por retorno, auxiliares por partida, tempo específico se disponível e identificação da fonte.</p><p>Potência média importada não é potência nominal do motor. CC motor-gerador e conversor estático também podem regenerar; a recuperação é configurável em qualquer equipamento compatível. Quando a potência já é líquida, o abatimento adicional deve ser zero. O termo conversor estático CC não significa necessariamente máquina sem engrenagens.</p><p>Horas de movimento por dia = partidas por elevador×tempo médio/3600. Espera = horas energizadas−movimento. Energia diária = kW×horas de movimento−retorno+W de espera×horas/1000+Wh de auxiliares×partidas/1000. Anual = diário×dias×unidades. Não há consumo fora da fronteira temporal declarada. Partidas diárias são uma hipótese própria; a contagem de pessoas no acesso não fornece sozinha viagens reais.</p><p>Apresentar kWh/ano, redução em kWh e percentual relativo à referência escolhida, e custo quando há tarifa. Redução negativa significa aumento; com referência zero, percentual indefinido. Exibir dois gráficos, memória por grupo e benefícios/limitações de cada tecnologia. Não classifica ou certifica o elevador pela ISO 25745.</p>`],
 ['pptx','Gráficos no relatório e PowerPoint editável',`<p>Os mesmos conjuntos de dados alimentam os gráficos do sistema, relatório e apresentação. São incluídas três curvas por grupo, quatro gráficos de atendimento e gráficos energéticos, além dos estudos separados. A prévia da tela Viagens repete os dados do grupo e não gera slides duplicados.</p><p>Após Calcular estudo completo, clique em Gerar PowerPoint editável. O arquivo PPTX tem textos, tabelas e gráficos nativos com planilhas incorporadas. Para editar valores no PowerPoint, selecione o gráfico e use Editar dados; essa edição não modifica o projeto salvo no programa. Logomarca e identificação do cliente acompanham o arquivo.</p><p>Qualquer alteração invalida os resultados e bloqueia relatório/apresentação até recálculo. Links de consulta verificam o acesso novamente antes do download. Versões históricas conservam os gráficos disponíveis no cálculo original; não recebem indicadores atuais calculados silenciosamente.</p>`],
 ['modelos','Escolha de modelo e origem das regras',`<p>Escolha NBR 5665 (preferencial) ou ISO 8100 (documento informado). Cada opção usa motor, parâmetros e relatório próprios; a troca guarda a configuração anterior e exige novo cálculo completo. Estudos anteriores sem seleção permanecem na NBR.</p><p>A opção ISO corresponde ao texto de trabalho ABNT N69 enviado pelo proprietário, em elaboração, não à reprodução certificada da ISO 8100-32 publicada. As fórmulas e critérios utilizados são identificados pelos itens do documento. Não se adiciona o fator NBR de 10% ao RTT do modelo alternativo.</p>`],
 ['iso-populacao','ISO · população por classe e pavimento',`<p>Escritórios: área interna útil × FU / área por pessoa. Classes: Superior 8–10 m²/pessoa, FU 80%; Intermediário 6–8, 80%; Ambiente aberto 5–7, 85%; Alta densidade 4–6, 90%. A classe atualiza as referências, e o usuário escolhe a densidade na faixa.</p><p>Residencial: tabela por classe e tipologia. Hotéis: 1–2 hóspedes por quarto. Saúde: leitos/consultórios ou área na ausência de detalhamento. Garagem: carros 1,4 pessoa/vaga; motos/bicicletas 1. A declaração maior é adotada por ambiente, conforme a regra do proprietário, e o documento pede arredondamento para cima da soma por pavimento. Descontos exigem condições específicas de adjacência, mesmo hall e livre utilização.</p><p>Exemplo de área: 6.851 m² × 85% / 7 = 831,907… → 832 pessoas no pavimento. O exemplo do anexo que indica 979 não aplica o FU mostrado; o programa usa a fórmula com utilização.</p>`],
 ['iso-rtt','ISO · RTT, paradas e reversão',`<p>Pcalc = lotação nominal × FC. N é interpretado como destinos sem o acesso. S = N[1−(1−1/N)^Pcalc]. H = N−Σ(i/N)^Pcalc, i de 1 a N−1. As paradas do ciclo são S+1, incluindo o acesso.</p><p>df = percurso/N; tv = df/v. O tempo de viagem de um piso considera aceleração e jerk. tperf = fechamento + atraso inicial + flight time − pré-abertura + abertura + atraso de fechamento. ts = tperf−tv. RTT = 2Htv+(S+1)ts+2Pcalc·tp. Capacidade = 300Pcalc×quantidade/RTT; intervalo = RTT/quantidade para grupo homogêneo.</p><p>Tabelas: transferência 5, ocupação 7, portas 8, movimento 9. Selecionar dados do fabricante identifica uma variação do método parametrizado. Os valores de performance impressos no Anexo D têm inconsistências; o sistema calcula tperf pela expressão e mantém a soma do RTT conferida.</p>`],
 ['iso-criterios','ISO · critérios, mínimo e partidas',`<p>A tabela 3 do documento tem faixas de intervalo. O usuário escolhe o menor limite (mais exigente), o maior ou um valor personalizado. A célula de demanda comercial Ambiente aberto está incompleta; o percentual informado é uma premissa explícita, inicialmente 12%.</p><p>O mínimo reavalia capacidade e intervalo para cada quantidade, mantendo a proporção dos grupos. O critério do documento para percurso acima de 24 m é 2 elevadores na ausência de mínimo local informado. Não é uma consulta automática à legislação municipal.</p><p>Partidas/ciclo = S+1. Percurso médio por partida = 2Hdf/(S+1). Máximo pelo tempo = 3.600×(S+1)/RTT, limitado pelo fabricante se informado. A necessidade usa o pico de 5 min extrapolado para uma hora e Pcalc. Intervalo não é tempo médio de espera; a análise é parametrizada, não uma simulação de duas horas.</p>`],
 ['iso-limites','ISO · hipóteses e limites da alternativa',`<p>O método utiliza controle convencional, pico de subida e população/altura uniformes para S e H. A composição diferente dessa distribuição é identificada como aproximação. Controle de destino ou múltiplos acessos principais exigem simulação específica; o cálculo parametrizado é bloqueado nesses casos.</p><p>Grupos do mesmo serviço precisam dos mesmos destinos e percurso. Zonas devem ser calculadas separadamente. Grupos com RTT diferentes utilizam consolidação aproximada por taxas de ciclo, identificada como premissa. Auditório permanece um componente de projeto fora do escopo do documento.</p><p>Relatório: identificação, dados por pavimento, parâmetros usados, S, H, tempos, RTT, Ch, critérios e formulário parametrizado do Anexo D do documento. Não é gerado Anexo C de simulação.</p>`],
 ['populacao','NBR · população calculada, declarada e adotada',`<p>A quantidade ou área de cada ambiente é convertida em pessoas pela regra do componente escolhido. A memória mostra a relação utilizada e o item da NBR 5665. Escritórios têm regras próprias para salas pequenas. Repetições multiplicam a quantidade calculada no mesmo andar.</p><p>Depois dos descontos elegíveis, compara-se a população calculada com a declaração daquele ambiente: <code>adotada = máximo(calculada líquida, declarada)</code>. Somam-se os valores adotados dos ambientes de cada andar e estudo uma única vez. O total final do estudo é arredondado para cima; as parcelas mantêm precisão integral.</p><p>Exemplo: ambientes calculados com 40 e 20 pessoas totalizam 60. Declarar 80 no primeiro faz adotar 80 + 20 = 100. Declarar 50 resulta em 50 + 20 = 70. Declarar 30 mantém 40 + 20 = 60. A declaração cobre todo o ambiente, inclusive suas repetições.</p><p>A confirmação do acesso à rua exclui os ambientes desse andar. Usos exclusivos de apoio e exclusões válidas por escadas rolantes também podem zerar parcelas. Valores brutos, declarações e motivos continuam na memória. “Como a população foi definida?” registra a justificativa e não altera a fórmula.</p>`],
 ['descontos','Descontos e usos complementares',`<p>O desconto adjacente é de 50%, nos pavimentos imediatamente acima e/ou abaixo do principal, com até 5 m de percurso. Em escolas, o campo próprio registra o percentual escolar: a referência adotada indica 30%, nas condições do item 5.1.3. Um valor diferente é identificado como premissa personalizada. Não acumule descontos sobre a mesma parcela; confirme as condições exigidas.</p><p>Garagens e restaurantes de uso exclusivo da edificação são registrados e desconsiderados da população, preservando paradas e percurso. Demandas externas recebem estudo separado, com seus grupos próprios: garagem com rampas e sem manobrista usa 1,4 pessoa/vaga e demanda de 10% em 5 min; restaurante usa 1 pessoa/1,5 m² e 6%. Auditório usa assentos e demanda/intervalo de projeto informados pelo usuário.</p>`],
 ['demanda','Demanda em cinco minutos',`<p>É a população que o sistema deve transportar na janela de análise: <code>demanda = população adotada × percentual do uso</code>. Por exemplo, 100 pessoas em escritórios em geral, com 12%, representam 12 pessoas em 5 minutos. Cada estudo separado usa seu próprio critério. O percentual não significa que todas as pessoas usarão o elevador ao mesmo tempo.</p>`],
 ['paradas','Paradas prováveis e percurso',`<p><code>N = p − (p − 1) × [(p − 2)/(p − 1)]^c</code>, onde p é o número de paradas possíveis, incluindo o acesso, e c é a lotação. N é uma média estatística e pode ser fracionário. O ciclo fechado inclui o acesso. O cálculo pressupõe a distribuição de destinos do modelo; não é uma lista de chamadas reais.</p><p>D é o percurso informado entre os extremos, em metros. O alerta <code>D &lt; (p − 1) × 2,80</code> é um critério de conferência definido para este programa. A precisão integral é mantida; casas decimais são reduzidas apenas na exibição.</p>`],
 ['ciclo','NBR · tempo de ciclo dos elevadores',`<p>O ciclo é uma viagem completa com retorno ao acesso. Os dois cálculos usam os mesmos componentes e bases de tempos diferentes:</p><ul><li><code>T1 = 2D/v</code>: deslocamento à velocidade nominal.</li><li><code>T2 = N/2 × ta</code>: parcela de aceleração e retardamento.</li><li><code>T3 = N × tp</code>: abertura e fechamento de portas nas paradas.</li><li><code>T4 = c × te</code>: entrada e saída de passageiros.</li><li><code>Adicional = 10% × (T3 + T4)</code>.</li><li><code>T = T1 + T2 + T3 + T4 + adicional + tempo adicional de ciclo</code>.</li></ul><p>v está em m/s e os tempos em segundos. A coluna NBR utiliza tabelas da referência de tráfego adotada; a coluna FAB utiliza os tempos e os parâmetros do fabricante informados. O tempo adicional é somado uma vez por ciclo. Não acrescente o mesmo atraso novamente em portas ou passageiros.</p>`],
 ['movimento','Aceleração, jerk e dados do fabricante',`<p>A aceleração a (m/s²) indica a variação da velocidade; jerk j (m/s³) indica a rapidez de mudança da aceleração. Para a parcela FAB do ciclo, <code>ta = 2 × (v/a + a/j)</code>. Quando <code>v &lt; a²/j</code>, usa-se <code>ta = 4 × √(v/j)</code>. A abertura e o fechamento são somados para formar tp.</p><p>Na base NBR, o tempo de aceleração/retardamento é interpolado na tabela adotada. Abaixo de 0,63 m/s, 2,50 s é uma extensão de projeto identificada; acima de 2,50 m/s utiliza-se 6 s conforme a base adotada.</p><p>Os alertas de conforto são parâmetros deste programa: aceleração acima de 1,00 até 1,60 m/s² em amarelo; acima de 1,60 em vermelho. Jerk em amarelo acima de 1,20 m/s³ até 2,50 m/s de velocidade ou acima de 1,60 m/s³ para velocidades maiores. Esses alertas não bloqueiam o cálculo.</p>`],
 ['capacidade','Capacidade em cinco minutos',`<p><code>Capacidade por elevador = 300 × c/T</code>, pois 5 minutos têm 300 segundos. Multiplica-se pela quantidade de elevadores do grupo e soma-se a capacidade dos grupos que atendem ao mesmo serviço. A comparação usa a precisão completa: capacidade ≥ demanda em 5 minutos. Lotação c é a adotada por cabina, não a população do edifício.</p>`],
 ['intervalo','Intervalo e quantidade mínima',`<p>Em cada grupo: <code>I = T/quantidade</code>. Para grupos com ciclos diferentes, o consolidado usa <code>Σ(T × quantidade)/quantidade total²</code>, uma aproximação por quantidade. Para ciclos iguais, coincide com T dividido pelo número total de elevadores.</p><p>O mínimo é encontrado ampliando blocos da composição informada, preservando características e proporções entre grupos, até atender simultaneamente à demanda e ao intervalo aplicável. Para grupos diferentes, a confirmação do despacho requer análise própria. Zonas independentes não recebem conclusão consolidada. O mínimo não inclui a restrição adicional de partidas/h nem as demais exigências do edifício.</p>`],
 ['distancia','Percurso médio por partida',`<p><code>d = 2D/N</code>. É a distância média estimada de uma partida até a próxima parada, incluindo o retorno ao acesso. O modelo assume distância total de ciclo igual a 2D. Com D = 30 m e N = 6, d = 10 m por partida.</p><p>A altura média entre pavimentos é <code>D/(p − 1)</code>. Com D = 30 m e p = 11, ela é 3 m. O elevador pode atravessar pavimentos sem parar; por isso as duas medidas são diferentes. A distância média não recalcula um pavimento de reversão estatístico.</p>`],
 ['partidas','NBR · partidas necessárias por hora',`<p>Uma partida é cada saída de uma cabina, inclusive o retorno vazio. Extrapola-se o pico da janela: <code>demanda horária equivalente = 12 × demanda em 5 min</code>. Em serviço comum, a demanda é distribuída entre grupos proporcionalmente à capacidade FAB.</p><p><code>Necessárias por elevador = (demanda horária do grupo/c) × N/quantidade</code>. Multiplicando pela quantidade obtém-se o total do grupo. A extrapolação pressupõe o pico mantido durante uma hora; não prevê pessoas únicas ou o movimento real do dia. Nas zonas independentes, a distribuição conjunta não é calculada.</p>`],
 ['maximo','Partidas máximas por hora',`<p>Usa-se o percurso médio d e um movimento ideal simétrico, limitado pela velocidade, aceleração e jerk. Em percursos curtos, o pico de velocidade é reduzido. O tempo de deslocamento é <code>d/u + tr</code>, em que u é a velocidade de pico viável e tr é o tempo de aceleração até u. Se <code>u ≤ a²/j</code>, <code>tr = 2√(u/j)</code>; nos demais casos, <code>tr = u/a + a/j</code>.</p><p><code>Tempo médio entre partidas = deslocamento + abertura + fechamento + c×te/N + 10%×(portas + c×te/N) + adicional de ciclo/N + permanência adicional</code>.</p><p><code>Máximo pelo tempo = 3.600/tempo médio</code>. Se o fabricante fornecer um limite de partidas por hora, adota-se o menor entre esse limite e o máximo pelo tempo. Zero no campo significa limite não informado. O indicador é uma estimativa operacional; o limite de serviço do equipamento precisa ser obtido do fabricante. A referência <code>3.600×N/T_FAB</code> é exibida separadamente.</p>`],
 ['exemplo','Exemplo numérico de conferência',`<p>Exemplo didático FAB: população 100, demanda 12%, dois elevadores iguais, lotação 10, duas paradas incluindo acesso, D = 10 m, v = 1 m/s, a = 1 m/s², j = 1 m/s³, abertura 1 s, fechamento 1 s, passageiro 1 s, adicional de ciclo 2 s e permanência adicional zero.</p><p>N = 2; ta = 4 s. T1 = 20; T2 = 4; T3 = 4; T4 = 10; adicional = 1,4; partida adicional = 2. Assim, T = 41,4 s. Capacidade FAB por elevador = 72,46 pessoas/5 min; grupo = 144,93. Intervalo do grupo = 20,70 s.</p><p>Percurso médio = 10 m; deslocamento médio = 12 s; tempo médio entre partidas = 12 + 2 + 5 + 0,7 + 1 = 20,7 s. Máximo pelo tempo = 173,91 partidas/h por elevador. Demanda horária = 144 pessoas; necessárias = 14,4 partidas/h por elevador, incluindo o retorno. Valores exibidos são arredondados para leitura.</p>`],
 ['escadas','Escadas, esteiras rolantes e população desconsiderada',`<p>Os dois tipos usam a mesma relação de tráfego. Capacidade horária total por sentido = capacidade unitária × quantidade em serviço. O tipo do equipamento é identificado no conjunto, sem modificar a relação. O uso da tabela enviada nas esteiras é uma premissa do proprietário, sem declarar equivalência normativa de todos os equipamentos.</p><p>A exclusão populacional utiliza a NBR 5665, item 5.1.6, com ligação ao acesso e capacidade para transportar a população. O programa verifica um caminho contínuo desde o pavimento imediatamente acima ou abaixo do principal. Uma interrupção ou gargalo mantém a população dependente no estudo dos elevadores.</p><p>Referências atuais de segurança: ABNT NBR 16734-1:2022, construção e instalação; ABNT NBR 16734-2:2023, melhoria da segurança de equipamentos existentes. Situação corrente identificada no catálogo DIN Media em 13/10/2026. A norma antiga fornecida foi retirada da base ativa. O texto integral das edições atuais ainda precisa ser consultado para validar os itens numéricos; nenhuma fórmula antiga é atribuída à edição atual.</p><p>Para cada trecho, escolha a tabela teórica enviada pelo proprietário ou informe a capacidade documentada do fabricante em pessoas/h, separadamente para subida e descida, como capacidade declarada para o estudo. O documento é opcional. <code>Capacidade na janela = capacidade horária × minutos/60 × utilização/100</code>. <code>Demanda do trecho = soma das populações dependentes × percentual de demanda/100</code>. Cada sentido deve atender à demanda; não se somam subida e descida. Com 4.800 pessoas/h, janela de 5 min e utilização 80%, são 320 pessoas por sentido.</p><p>Informe os sentidos, larguras e capacidades da rede. A composição deve estar marcada como servida. A análise atual não exige confirmação manual nem documento, mas mantém a população nos elevadores quando faltar continuidade ou capacidade de atendimento nas condições informadas.</p>`],
 ['operacao','Operação anterior e permanência adicional',`<p>Estudos legados preservam pesos normalizados, fretado e almoço: 80% da população por hora no leve/moderado e 95% no pesado. A tabela enviada agora e as medições reais são bases próprias, sem alterar esses estudos automaticamente.</p><p>Nos ciclos NBR, capacidade operacional = soma de 300×lotação×quantidade/(T+N×permanência). No ISO, usar Pcalc, RTT e S+1. A permanência aqui é complemento operacional; não reescreve o resultado normativo. Veja Performance de atendimento para a divisão da oferta simultânea no almoço.</p>`],
];
export const MANUAL_SECTIONS=[
 ['unidades91','Atualização 9.1: preencher e copiar cada elevador',`<ol><li>Em Parâmetros, selecione o grupo e escolha sua Aplicação do edifício. No Básico, escolha a aplicação na própria coluna do grupo.</li><li>Marque os pavimentos atendidos na matriz e nos flags individuais. Confira as Paradas (incluindo acesso), preenchidas automaticamente.</li><li>Na tabela de cada unidade, use Copiar unidade para escolher os destinos no mesmo grupo. A origem fica desabilitada. A cópia substitui características, referência dimensional, tempos e atendimento dos destinos; as identificações são preservadas.</li><li>Em Dados de portas, fabricante e movimento por elevador, informe os tempos ou use Preencher automaticamente. Leia as premissas geradas, confira com o fabricante e ajuste manualmente. Copiar tempos e movimento altera somente esse conjunto de dados nas unidades selecionadas.</li><li>Informe a transferência como tempo de entrada e saída em segundos por parada. Tempo adicional de partida é um campo distinto, sem multiplicação por pessoas. A pré-abertura exibe o campo em segundos quando ativada.</li><li>Em Parâmetros dimensionais, no levantamento existente, informe frente e lado internos da cabina. Confira a área calculada, a faixa da tabela para cada capacidade e os alertas. A partir de 21 passageiros, o mínimo segue a fórmula geral; acima de 33, o máximo também segue a fórmula geral fornecida.</li><li>Após qualquer alteração ou cópia, clique em Calcular estudo completo. Confira cada grupo e unidade, então gere relatório ou apresentação. Relatórios arquivados permanecem preservados.</li></ol><p>Não existe mais um seletor de precisão: o cálculo mantém precisão integral. Os textos de tempos substituem os rótulos repetidos anteriores. A cópia de unidades só permite destinos do mesmo grupo; para outro grupo, use a cópia de grupo já existente.</p>`],
 ['licencas90','Escolher módulo e administrar acessos',`<p>Use Novo Básico ou Novo Avançado para criar um estudo separado. O projeto atual é salvo antes da troca quando há edição autorizada. Projetos existentes preservam seu módulo; não há conversão automática nem substituição dos cálculos. No Básico, preencha as colunas, a definição da população e os dados de identificação, depois pressione Calcular estudo. Campos obrigatórios vazios aparecem em laranja. Qualquer edição invalida os resultados e bloqueia o relatório até novo cálculo.</p><p>Em Assinatura: Básico R$15,00/mês ou R$162,00/ano; Avançado R$25,00/mês ou R$270,00/ano. Os anuais incluem desconto de 10% sobre 12 mensalidades. Cobrança real permanece desativada: registrar aquisição exige CPF válido, e a ativação demonstrativa é revisada pelo administrador. CPF tem validação matemática e vínculo único de cadastro, sem verificação de identidade externa. O número completo não é conservado em texto nem exposto em auditoria.</p><p>A primeira aquisição demonstrativa do Básico concede 30 dias no Avançado, uma única vez por cadastro vinculado ao CPF. A faixa do Avançado mostra os dias restantes e apresenta oferta de continuidade nos últimos sete dias. Após vencer, abra Projetos salvos e o estudo: será possível abrir para imprimir/PDF ou baixar o último relatório formatado arquivado. Edições, novas apresentações editáveis, exportação de estudo e compartilhamentos ficam bloqueados. Links existentes também dependem de licença vigente do responsável. Relatórios anteriores a este recurso precisam ser calculados e salvos uma vez durante acesso ativo para formar o arquivo histórico.</p><p>O administrador acessa Administração de licenças na tela Assinatura ou pelo botão de Equipe e acessos. Escolhe usuário e módulo, informa vencimento ou marca concessão permanente. Pode revogar concessões e gerar chave temporária com vencimento fixo. A chave é vinculada ao usuário escolhido, usada uma vez e exibida somente ao gerar. Concessão Avançada inclui o Básico. Licença não concede acesso aos projetos de terceiros nem amplia a audiência privada da hospedagem.</p><p>Na opção educativa, informe faculdade, data de emissão e comprovante PDF, PNG ou JPEG de até 1,8 MB. O acesso depende da conferência da matrícula pelo administrador. A primeira aprovação concede seis meses gratuitos em ambos os módulos. A renovação exige documento diferente, com data posterior, e acrescenta seis meses a partir do vencimento vigente, ou da aprovação quando já vencido. Documento pendente não libera recursos. Somente o titular e o administrador podem baixar o comprovante.</p>`],
 ['transportes89','Configurar escadas e esteiras com confirmação única',`<p>Na caixa Equipamentos de transporte do edifício, responda uma única vez: O prédio terá escadas e/ou esteiras rolantes? Sim habilita a coluna conjunta na tabela de pavimentos. Marque os andares atendidos para abrir a aba Escadas e esteiras rolantes. A identificação de cada conjunto permite escolher Escada rolante ou Esteira rolante, com os mesmos campos e a mesma relação de tráfego.</p><p>Capacidade na janela = capacidade unitária por hora × quantidade em serviço × minutos/60 × utilização/100. Demanda = população × demanda percentual/100. Os sentidos são verificados separadamente. A tabela enviada é premissa do estudo; para um produto diferente, informe a capacidade do fabricante. Continuidade, desnível e capacidade continuam sendo avaliados para o abatimento da população dos elevadores.</p><p>Esteiras locais/horizontais usam a mesma janela e percentuais. Informe a população do trecho para comparar a demanda; vazio mantém a indicação de demanda não avaliada. Seu comprimento/velocidade fornece o tempo de viagem sem acrescentar capacidade de transporte. Estes trechos isolados não abatem automaticamente população de andares. Cadastros anteriores são preservados. <strong>Não</strong> suspende a análise ativa, mantendo os dados; Sim permite reativá-los. Alterar parâmetros invalida o relatório até o recálculo completo.</p>`],
 ['configurar88','Consultar caixa/cabina e liberar configuração de escadas',`<p>Abra Parâmetros dimensionais e escolha casa de máquinas, fabricação, tipo de cabina e entradas. Os dados de porta, velocidade e capacidade acompanham cada elevador. Confira frente/lado da cabina e intervalos mínimo/máximo da caixa. Havendo variantes, selecione a linha desejada no campo de cada elevador. Registros inconsistentes aparecem para conferência. Dados reais do fornecedor substituem referências por campo, sem alterar medidas existentes.</p><p>Para configurar escadas, confirme sua utilização e marque ao menos um flag na coluna de escadas de Pavimentos e atendimento por grupo. Só então a aba Escadas e esteiras rolantes fica disponível e o controle de atendimento pode ser ativado. Selecionar um andar preenche o caminho desde o acesso; é possível desmarcar cada pavimento. Retirar todas as marcações oculta a aba e desativa o abatimento, preservando os dados cadastrados.</p><p>A configuração das escadas não exibe Documento do fabricante nem Confirmações. Informe trechos, existência/quantidade nos dois sentidos, degraus, velocidades, inclinação, desnível e capacidades conforme a base adotada. Não há confirmação manual obrigatória para liberar o cálculo. Alterações exigem recálculo completo antes de emitir ou compartilhar documentos.</p>`],
 ['dimensoes87','Consultar última altura e poço',`<p>Abra Parâmetros de cálculo → Parâmetros dimensionais. Em cada grupo, selecione com ou sem casa de máquinas e informe a altura da porta e da cabina. A fabricação pode ser filtrada como padronizada ou especial. A consulta acompanha capacidade, velocidade e percurso de cada coluna de elevador; os resultados e a origem aparecem na mesma tela.</p><p>Na proposta do fornecedor, preencha casa de máquinas e alturas do produto. Última altura mínima e poço mínimo vazios recebem a referência quando há correspondência na tabela. Digite os dados reais do fabricante para substituí-los; máximos, demais dimensões e medições continuam a ser declarados pelo fornecedor. Sem correspondência, solicite informação do fabricante: o sistema não inventa valores.</p><p>A última configuração cadastrada pela empresa, com modelo, capacidade, velocidade, portas e variante dimensional compatíveis, pode ser reutilizada. Dados de outro fornecedor não são aplicados automaticamente. O relatório e o PowerPoint identificam os valores provisórios e os declarados. Recalcule o estudo após editar os parâmetros para liberar documentos atualizados.</p>`],
 ['colunas86','Preencher os elevadores e nomear os grupos',`<p>Em Parâmetros de cálculo, escolha o grupo e edite Nome do grupo. Informe a quantidade de elevadores; cada coluna apresenta uma única capacidade em pessoas, a massa adotada por pessoa, velocidade em m/s, abertura livre e tipo de porta. Os retornos em kg e em m/min são automáticos. Selecione uma sugestão da tabela de massa ou velocidade ou digite outro valor válido.</p><p>Os campos comuns repetidos de lotação, velocidade e porta foram retirados. Estudos anteriores preservam seus dados como origem das colunas até a edição individual. Desde a versão 9.1, tempos e movimento são individuais; o levantamento dimensional existente continua cadastrado por grupo. Calcule o estudo completo após qualquer alteração para liberar relatório, apresentação ou compartilhamento.</p><p>Em Cálculo de tráfego, confira o estudo separado de cada grupo, com população, demanda, capacidade, intervalo e mínimo estimado próprios. As abas de gráficos, o relatório e a apresentação incluem esses estudos. A visão consolidada é apenas informativa. Nomes personalizados acompanham os cálculos; copiar um grupo preserva a identificação do destino.</p>`],
 ['selecao851','Atualização 8.5.1: seleção automática de andares para escadas',`<p>Todos os flags de escadas podem ser editados, inclusive o do acesso principal. Ao marcar um andar diferente do acesso, o sistema marca também o acesso e todos os pavimentos intermediários, seguindo a ordem física da tabela. Exemplo: com acesso no andar 0, marcar o andar 3 seleciona 0, 1, 2 e 3. A regra também funciona abaixo do principal e com letras ou subsolos, sem renomear andares.</p><p>Depois, é possível desmarcar qualquer andar. A remoção afeta somente o flag escolhido; os demais permanecem como estavam. Uma lacuna aparece em vermelho. Se o acesso principal for desmarcado, a ligação não é considerada contínua para excluir população dos elevadores. Marcar novamente um destino preenche o caminho até ele. As alterações exigem revisão da capacidade operacional e recálculo completo antes de emitir relatório.</p><p>Cadastros anteriores, nos quais o acesso ficava bloqueado, preservam sua interpretação até serem editados. A atualização não altera os links históricos já gerados. O modo somente leitura continua protegendo os dados.</p>`],
 ['configuracao85','Atualização 8.5: equipamentos, elevadores e pendências',`<p>Em Parâmetros de cálculo, responda uma única vez se o prédio terá escadas e/ou esteiras rolantes. Confirmar Sim e selecionar os pavimentos atendidos abre a aba conjunta Escadas e esteiras rolantes, ao lado de Dados dos Elevadores do estudo e Parâmetros dimensionais. A configuração saiu do Cálculo populacional. Confirmar Não conserva os dados para consulta futura e os retira da análise ativa. Projetos anteriores com rede de escadas ativa são reconhecidos como já confirmados.</p><p>Na tabela Pavimentos e atendimento por grupo, marque os andares servidos por escada rolante. Os trechos usam esses andares e o principal físico escolhido. As quantidades acima/abaixo acompanham a seleção. Uma lacuna entre o principal e o último pavimento selecionado aparece em vermelho; confira a ligação antes de considerar a exclusão populacional. Configure os conjuntos, sentidos, quantidades, larguras e capacidades na aba Escadas e esteiras rolantes. As confirmações operacionais precisam ser revistas quando o atendimento muda.</p><p>Clique num grupo de elevadores para ver sua tabela. Cada elevador tem uma coluna com capacidade, velocidade, abertura livre em mm, tipo de porta e flags de pavimentos. O número de paradas é automático pela seleção, incluindo o principal. Desde a versão 9.1, tempos e limite PPH são individuais; dimensões existentes continuam por grupo. Valores individuais prevalecem sobre os campos de referência do grupo. O cálculo e as saídas identificam os equipamentos ou conjuntos idênticos. Destinos independentes seguem a análise por zonas; destinos sobrepostos exigem uma distribuição de demanda definida, sem somar capacidades automaticamente.</p><p>Ao alterar a quantidade, configurações retiradas ficam arquivadas nos dados do projeto. Alterar um flag de atendimento do grupo na matriz aplica a escolha a todos os elevadores desse grupo; os flags da tabela individual permitem diferenças. Renomear andares preserva o vínculo físico de cada equipamento.</p><p>No fim de cada tela, confira etapa(s) com preenchimento pendente. Cada item é clicável e abre a aba, o grupo ou a composição correspondente, rola até o campo e coloca o foco nele. Na tela de cálculo, a lista reúne as pendências do estudo. Após qualquer alteração, recalcule antes de imprimir ou compartilhar.</p><p>Escadas e esteiras compartilham os parâmetros de janela, demanda e utilização e a mesma relação de vazão. Identifique o tipo em cada conjunto. Esteiras locais/horizontais mantêm identificação, comprimento, velocidade, largura, quantidade, capacidade declarada e população opcional para comparar a demanda. Sua capacidade na janela e atendimento aparecem no relatório e PowerPoint. Um trecho horizontal isolado não exclui população dos elevadores.</p>`],
 ['populacao84','Atualização 8.4: conferir população e copiar dados',`<p>Em Cálculo populacional, confira o nome automático Andar 01 e informe o texto livre em Indicação do ambiente. O nome acompanha o andar servido sem mudar sua marcação. A população calculada continua apresentada mesmo no acesso, em uso exclusivo ou quando a participação é desativada. Próximo à declaração, confira a população destinada aos elevadores e o aviso da parcela não computada. Se faltam dados em outro ambiente, a população local ainda pode aparecer, mas o total aguarda o preenchimento válido de todo o estudo.</p><p>Ao clicar em Copiar, marque O que deseja copiar: componente/destinação/participação, área ou quantidade/repetições, população declarada, indicação/observações, parâmetros do estudo separado, descontos/exclusões ou solicitação de escadas. Escolha os pavimentos de destino (origem inibida) ou Novo pavimento. Também há modos por quantidade e mesmo andar. Campos não selecionados ficam com valores iniciais; confirme os dados antes de calcular. Acesso principal, confirmações locais e a rede de escadas nunca são copiados. Ambientes já preenchidos no destino são preservados.</p><p>Na opção População não computada no estudo quando atendida por escadas rolantes, solicite a avaliação, configure o caminho completo e confira os sentidos e as capacidades. O balanço mostra população atendida e saldo. Atendimento parcial deixa a diferença nos elevadores; não é uma dispensa normativa automática. Exemplo: 160 pessoas e atendimento equivalente a 100 deixam 60 no estudo. Preencha janela, demanda percentual e utilização conscientemente: eles alteram a capacidade equivalente.</p><p>Alterações retiram os resultados anteriores. Clique em Calcular estudo completo para atualizar tráfego, gráficos, relatório e PowerPoint. Relatórios e links históricos preservam sua versão original. A hospedagem continua privada, sem ampliação de acesso ou cobrança.</p>`],

 ['acesso83','Acesso principal independente da marcação',`<p>Em Pavimentos e atendimento por grupo, escolha o Acesso / Andar principal na linha física correta. A escolha mantém os nomes de todos os andares e desmarca o acesso anterior. Exemplo: numa tabela −2, −1, 0, 1, selecionar −1 como principal preserva exatamente essa sequência. O andar 0 pode continuar sendo um destino atendido.</p><p>A população excluída no acesso, os pavimentos imediatamente adjacentes, as distâncias dos descontos, as ligações de escadas e a origem do antecipador acompanham o principal selecionado. Ao trocar o acesso, os resultados são invalidados e é necessário recalcular. Se o antigo acesso tinha apenas um campo vazio, complete a população que volta a participar. As confirmações de escadas precisam de nova conferência.</p><p>Aviso de acessibilidade: ABNT NBR 16858-3:2022, item 5.4.2.3.2 a), trata da identificação dos botões por símbolos coerentes com a nomenclatura dos pavimentos. Números, caracteres e pictogramas são possibilidades; a sequência −2, −1, 0, 1, 2 etc. é preferencial. A seleção de um subsolo como acesso não comprova, por si só, descumprimento. O sistema alerta para conferir a correspondência entre botões e identificação do edifício, sem declarar uma infração automática e sem bloquear o cálculo. O aviso e o principal selecionado aparecem no relatório e no PowerPoint.</p><p>Os projetos anteriores sem uma seleção independente conservam como acesso o andar que já estava marcado 0. Alterar a marcação manualmente é uma ação diferente de selecionar o acesso. Não se disponibiliza a cópia da norma; adquira a publicação oficial da ABNT para a verificação completa.</p>`],
 ['atualizacao82','Descontos, cópias e antecipador de destino',`<p>Em edifícios comerciais de escritórios, o desconto de 50% pode ser selecionado nos pavimentos imediatamente acima e imediatamente abaixo do acesso, até 5 m de percurso: máximo de dois pavimentos distintos. A quantidade de ambientes no mesmo andar não duplica esse limite. Outros pavimentos são recusados; confira os dados e as condições aplicáveis.</p><p>Copiar composição abre as flags dos pavimentos cadastrados. Marque um ou vários destinos ou Novo pavimento. O pavimento de origem fica desabilitado. Os dados são copiados como novos ambientes, preservando os já preenchidos; um campo vazio gerado automaticamente é substituído. Descontos, escadas e confirmações locais não são copiados. Um novo pavimento na tabela física pede distância e revisão do atendimento por grupo. O modo anterior de quantidade e andares seguintes/mesmo andar continua como opção.</p><p>Copiar distância abre flags de destinos; a origem e a base inferior ficam desabilitadas. Somente destinos marcados são alterados. Após as cópias, recalcule o estudo completo para gerar relatórios e apresentações.</p><p>A frase sobre os conjuntos atenderem as mesmas paradas, hall, acesso principal e uso é apenas um aviso. Não há flag obrigatória para liberar cálculo. A matriz de pavimentos continua separando zonas distintas, preservando suas populações e critérios; soma de capacidades não comprova atendimento de uma zona insuficiente.</p><p>Na proposta, ative Antecipador de destino. A ocupação inicia em 80%, editável por digitação ou passos de 1%, de 1% a 100%. A lotação média equivalente é capacidade nominal × ocupação/100 e alimenta o cálculo do fornecedor, sem reduzir a capacidade nominal do equipamento.</p><p>Escolha o sistema: genérico, Schindler PORT, KONE Destination, Otis Compass 360, TK Elevator AGILE ou outro. A seleção identifica o produto, sem reproduzir algoritmos proprietários ou aplicar ganhos fixos por marca. Escolha agrupamento Monte Carlo ou RTT/paradas documentados. No documentado, registre RTT, paradas médias sem acesso, distância média, relatório e confirmação das mesmas condições. A proposta deve ser salva e calculada.</p><p>Compare o gráfico de capacidade de entrada com o convencional à mesma ocupação e consulte a memória. O resultado é preliminar: não calcula espera, formação de lotes ou tráfego misto. Perfis de almoço e saída conservam a referência convencional. PPH e consumo da proposta usam o cenário de entrada e a utilização do pico declarada, sem garantia de economia diária. A classificação permanece pendente de validação por simulação do fabricante. Relatório e PowerPoint incluem o gráfico, método, ocupação e premissas.</p>`],
 ['grupos81','Condição de fornecimento e cópia de grupos',`<p>O campo de condição de fornecimento apresenta Obra nova, Retrofit / modernização e Substituição total. A alteração do nome preserva os projetos e levantamentos cadastrados.</p><p>Em Dados dos Elevadores do estudo, clique em Copiar dados do grupo. Escolha a origem e marque um ou vários destinos por flags. A origem permanece visível e desabilitada como destino; ao trocar a origem, ela é retirada da seleção. Também é possível criar um novo grupo até o limite de 20.</p><p>Confirmar cópia substitui equipamentos, tempos, dimensões e atendimento por pavimento dos grupos escolhidos. Nomes e identificações dos destinos são mantidos. A origem e os grupos não marcados permanecem preservados. Recalcule o estudo completo antes de emitir relatório ou apresentação.</p>`],
 ['colaboracao','Responsável, fornecedor e contratante',`<p>Salve e calcule o estudo-base, abra Fornecedores e contratante e registre os convites. A hospedagem continua privada, restrita ao proprietário. Nenhum email é enviado automaticamente. Liberar uma pessoa na hospedagem é uma decisão separada, após aprovação do proprietário.</p><p>O fornecedor preenche somente sua proposta. O responsável também pode cadastrar uma proposta em nome de um fornecedor registrado, com sua própria autoria auditada. O contratante consulta todas as propostas autorizadas, gráficos e relatórios. Use Salvar e calcular minha proposta para atualizar sua revisão sem modificar o estudo-base.</p><p>O administrador define cargos e equipe: Analista de estudos trabalha nos registros próprios ou delegados; Gerente nos da equipe; Diretor tem acesso total aos estudos/clientes; Administrador também gerencia cargos e autorizações. Cliente e fornecedor recebem somente acesso por projeto. A exportação JSON depende de aprovação do administrador para o funcionário; o administrador possui essa autorização.</p>`],
 ['links-auditoria','Compartilhamentos aprovados e numerados',`<p>Use Compartilhar / solicitar autorização. Escolha todas as propostas permitidas ao seu perfil ou somente um fornecedor. Links de consulta permitem visualizar e imprimir. Links de edição exigem integrante já autorizado e sua identidade de acesso. O responsável pode gerar um link para um fornecedor identificado editar somente sua própria proposta. Não concedem alteração anônima nem ampliam o privilégio do destinatário.</p><p>Escolha um dia (24 horas), prazo informado ou ilimitado até revogação. Clientes e fornecedores registram solicitações; o administrador ou responsável do estudo aprova. Gerador, número, aprovador, escopo, prazo e revogação ficam na auditoria. O link aprovado aparece para cópia e entrega manual. Reaprovar gera um endereço novo. O relatório específico recebe o nome do fornecedor no arquivo.</p><p>Importar JSON cria um rascunho independente, sem trazer permissões ou credenciais. Exportar dados JSON e comparações CSV exige cálculo completo e autorização de exportação da equipe. Relatórios e PowerPoint permanecem disponíveis aos perfis de consulta autorizados.</p>`],
 ['catalogo-produtos','Últimos dados de equipamentos e conta de energia',`<p>Na proposta, escolha modelo, capacidade e velocidade. Se houver cadastro da empresa para essa combinação, os parâmetros do produto são preenchidos automaticamente. Confira os dados e salve o produto no catálogo. Quando diferem do último cadastro, veja o email do autor anterior e confirme Sobrescrever cadastro anterior ou mantenha o registro.</p><p>Na conta de energia, anexe PDF, PNG ou JPEG de até 2 MB e confira consumo mensal, custo variável e total. A leitura por IA está preparada, mas requer configuração da credencial e do modelo do serviço. Sem essa configuração, preencha os valores manualmente. A leitura assistida nunca aprova valores nem altera a tarifa automaticamente.</p>`],

 ['revisao8','Alterações da versão 8',`<p>Firma instaladora passa a Empresa responsável, mantendo os dados já registrados. Dados dos Elevadores do estudo reúne as entradas dos equipamentos. O resumo Tempos do fabricante e premissas de movimento acompanha esses dados automaticamente e identifica a origem de catálogo quando utilizada.</p><p>Novo estudo com campos vazios inicia um cadastro sem quantidades, lotação, velocidade ou tempos presumidos. Em Pavimentos e atendimento por grupo, defina de 1 a 20 grupos. Novos grupos aparecem vazios e campos necessários ficam em laranja. Dados de grupos existentes são mantidos. Ao reduzir a quantidade, o arquivo do estudo preserva os grupos retirados em um registro separado.</p><p>O painel O que falta para calcular? informa as pendências por etapa. Paradas prováveis já podem aparecer quando lotação e paradas são válidas; o cálculo completo exige também percurso, quantidade, velocidade, portas, tempos, população e confirmações aplicáveis. Zero é aceito nos campos que o permitem, como partida adicional e PPH fabricante não informado.</p><p>Rascunhos incompletos podem ser salvos e reabertos. Relatórios e apresentações continuam bloqueados até o cálculo completo. Os estudos anteriores conservam seus dados; editar a estrutura física ou definir grupos ativa o novo fluxo de preenchimento por andar.</p>`],
 ['dimensoes8','Obra nova, retrofit e dimensões',`<p>Em Parâmetros de cálculo, selecione a condição de fornecimento: Obra nova, Retrofit / modernização ou Substituição total. A aba Parâmetros dimensionais reúne os dados do gestor/contratante, separados dos dados do fornecedor.</p><p>No retrofit ou substituição total, o gestor informa, por grupo e em mm: frente e lado da caixa, última altura, poço, frente/lado/altura de cabina, largura/altura/tipo de porta e quantidade de portas da cabina. Sem esses dados, o cálculo completo fica pendente no fluxo novo. Na obra nova, a proposta do fornecedor apresenta faixas mínima e máxima de frente/lado de caixa, última altura e poço.</p><p>Em Fornecedores e contratante, o fornecedor registra também frente/lado/altura interna de cabina, abertura/altura/tipo/quantidade de portas e disposição dos acessos. No retrofit, precisa conferir em loco, registrar medidas independentes do gestor, data e responsável e informar o tipo de porta existente e se será mantida ou substituída. Divergências e incompatibilidades com as faixas declaradas aparecem na comparação, relatório e apresentação.</p><p>Dimensões são dados documentados do fabricante. Velocidade, portas, cabina e quantidade/disposição dos acessos identificam a configuração. O sistema não inventa folgas ou mínimos normativos a partir desses atributos. As verificações geométricas básicas e a comparação com faixas declaradas não certificam a instalação.</p>`],
 ['catalogo-dimensional','Consulta global e reutilização de produtos',`<p>A administração/diretoria consulta o catálogo global de produtos salvos. O gestor consulta as configurações dos fornecedores autorizados no projeto. Use Consultar catálogo dimensional, em Parâmetros, e filtre por empresa, modelo, velocidade, lotação, tipo de porta, largura/altura de portas, frente/lado/altura de cabina e quantidade de portas. A tabela mostra as faixas mínimas/máximas de caixa, última altura e poço, autor e revisão.</p><p>Usar configuração preenche os dados do produto e tempos do grupo escolhido, preservando sua quantidade de elevadores, destinos, percurso e levantamento do gestor. Confira os valores e calcule novamente. O último cadastro também pode preencher a proposta por modelo, velocidade, lotação e porta. Havendo variantes dimensionais, confira a configuração indicada ou consulte os filtros.</p><p>Salvar uma proposta dimensional completa registra sua configuração no banco do catálogo. Alterar dados de configuração já existente exige confirmação de sobrescrita e mostra o email do autor anterior. Novas variantes dimensionais têm chaves próprias. Concorrência de edição não pode substituir silenciosamente uma revisão.</p><p>Medições e confirmações em campo pertencem ao projeto. A reutilização de produto limpa esses campos e exige nova conferência. O catálogo global da administração preserva os dados registrados para consulta; a consulta de reutilização não entrega levantamento de outro projeto ao fornecedor.</p>`],
 ['pavimentos','Pavimentos, distâncias e atendimento por grupo',`<p>Em Parâmetros, a tabela parte da maior quantidade de Paradas (incluindo acesso) dos grupos. Cada linha representa um pavimento físico. Entre Posição física e Marcação do andar, o flag Acesso / Andar principal permite escolher somente um acesso; a escolha desmarca os outros e preserva todas as marcações. O principal pode estar no subsolo, por exemplo −1 ou S1. A linha superior é a mais alta. No campo Distância desde o inferior, use Copiar distância para abrir a caixa de seleção de destinos por flags. A origem e a base inferior ficam desabilitadas. Somente os intervalos marcados recebem o valor; Selecionar todos os destinos é opcional. Informe a distância desde o pavimento imediatamente inferior e selecione os grupos que atendem cada andar. Ajustar quantidade de pavimentos amplia ou reduz a tabela, protegendo andares com composições. Ao copiar um grupo, copia-se também sua coluna de atendimento.</p><p>Ative Utilizar tabela de pavimentos no cálculo para usar a geometria no estudo. Editar marcação, distância ou atendimento também ativa a tabela. Ela começa desativada em estudos anteriores para preservar os percursos informados até a conferência. Quando ativa, Paradas e Percurso de cada grupo são derivados das suas seleções e das distâncias físicas, incluindo andares intermediários sem parada.</p><p>Alterar uma marca numérica preserva os pavimentos abaixo e renumera os números acima. Letras como S, S1 e S2 são mantidas e não consomem um número. Exemplos de baixo para cima: −2, −1, S, 0, 1 e −2, −1, S2, S1, 0, 1. Marcações não podem se repetir e têm no máximo dois caracteres, incluindo o sinal de menos. Portanto −1 é aceito e −10 precisa de outra marcação de até dois caracteres. O limite de identificação é um critério do programa. O pavimento de acesso é 0 e cada grupo deve atendê-lo neste modelo de subida. A tabela exige dois a duzentos pavimentos.</p><p>Ao ativar/editar a estrutura no fluxo novo, o sistema cria automaticamente pelo menos uma composição por andar, sem preencher uma área presumida. As abas de andar mostram as composições daquele pavimento. Preencha área, quantidade ou declaração. O acesso 0 permanece desconsiderado. Em Cálculo populacional, escolha Andar servido pela composição na lista da tabela ativa. Populações do andar 0 são desconsideradas e distâncias para descontos são derivadas da geometria. Cópias para andares seguintes seguem a ordem física, inclusive S1/S2. O sistema avisa se não houver pavimentos suficientes.</p><p>Grupos com exatamente os mesmos destinos compartilham uma zona. Destinos diferentes geram cálculos por zona com população, percurso, PPH, mínimo e gráficos próprios. Sobreposição em andar populado exige distribuição explícita da demanda em estudos próprios, para evitar duplicação. Cada zona precisa de atendimento ao acesso 0. A soma de capacidades é apenas informativa. Transferências e controle de destino exigem outra análise. O modelo ISO parametrizado bloqueia distâncias diferentes entre seus destinos servidos. Medições globais não são distribuídas automaticamente entre zonas.</p>`],
 ['modelo','0. Escolha o modelo do estudo',`<p>No início, selecione NBR 5665 (preferencial) ou ISO 8100 (documento informado). A NBR mantém os formulários e o Anexo A. A opção ISO usa classe de ocupação, FC, S, H e RTT, com formulário parametrizado do Anexo D do texto de trabalho fornecido.</p><p>Ao trocar, os dados próprios de cada modelo ficam guardados; os resultados anteriores são retirados. Confira a população e clique em Calcular estudo completo. Para comparar os modelos, salve um cenário de cada um. A comparação identifica os motores e não mistura suas fórmulas.</p><p>No modelo ISO, confira classe, área por pessoa, utilização, ocupação da cabina, origem dos tempos, faixa de intervalo e premissas. O documento está em elaboração e a alternativa não certifica conformidade com a edição publicada da ISO. Controle de destino e múltiplos acessos requerem simulação fora deste protótipo.</p>`],
 ['inicio','1. Conheça as cinco telas do estudo',`<p>Entre com sua conta autorizada. O menu principal possui cinco telas: Cadastro, Parâmetros de cálculo, Cálculo populacional, Gráficos de performance e economias e Cálculo de tráfego. Use Continuar e Voltar ou escolha diretamente a etapa no menu. Mudar de tela preserva os dados do mesmo estudo.</p><p>Comece em Cadastro, com cliente e identificação do projeto. Em Parâmetros de cálculo, escolha NBR 5665 ou ISO8100, aplicação do edifício, critérios e elevadores principais/separados. Em Cálculo populacional, abra uma composição por vez e confira as parcelas de cada andar e o total.</p><p>Em Gráficos, use os painéis Atendimento, Energia e potência ou Viagens. As configurações ficam recolhidas em suas próprias seções. Na tela Cálculo de tráfego, clique em Calcular estudo completo para aplicar população e recalcular todos os estudos. Os relatórios só ficam disponíveis com o cálculo atualizado.</p><p>Em Projetos e ferramentas, abra Projetos salvos, Clientes cadastrados, cenários, personalização e manuais. Salvar projeto grava o rascunho ou o estudo calculado na sua conta. Alterações também têm salvamento automático; confira a indicação no rodapé. Em conflito de revisão, reabra a versão salva antes de continuar.</p>`],
 ['cadastros','2. Atualize clientes e seus dados',`<p>Na tela Cadastro, preencha empresa, endereço, telefone, email e contato e clique em Salvar cadastro do cliente. Também é possível cadastrar em Projetos e ferramentas, Clientes cadastrados. No cliente existente, clique em Atualizar dados, edite e confirme em Atualizar dados do cliente. O registro mantém sua identidade e pode ser reutilizado em novos estudos. No Cadastro de outro projeto, escolha o cliente na lista Escolher cliente cadastrado. O mesmo cliente pode ser usado em vários projetos. Em Clientes cadastrados, Usar no estudo preenche o projeto aberto; Novo projeto para este cliente inicia um estudo independente com os contatos preenchidos. O rascunho atual é salvo antes de iniciar outro, quando há acesso de edição. Depois de aplicar dados a um estudo, calcule novamente. Cada projeto mantém sua identificação e uma cópia dos contatos utilizados. Alterar o cadastro base não reescreve os contatos de projetos anteriores ou os relatórios compartilhados. Para aplicar dados novos a um projeto existente, selecione o cadastro novamente ou use Usar no estudo.</p><p>Em Minha empresa / meus dados, preencha seu nome e contatos e clique em Atualizar dados do usuário. O email de acesso é a identidade da conta ChatGPT e permanece vinculado ao login. O email de contato pode ser diferente.</p><p>Preencha também os dados da empresa assinante e a personalização do relatório. Clique em Atualizar dados da empresa e relatório para salvar. Os dados pessoais de contato não são inseridos automaticamente no relatório.</p>`],
 ['projeto','3. Identifique o contratante e o local do projeto',`<p>Selecione um cliente cadastrado ou informe seus dados no estudo. Registre nome do projeto, endereço, contato no local e telefone. Esses dados aparecem na primeira página do relatório. As informações de proprietário, autor, construtor, responsável técnico e empresa responsável completam a página final do formulário.</p>`],
 ['composicoes','4. Monte o cálculo populacional',`<p>Escolha a aplicação principal e preencha as composições geradas por andar. A descrição comercial agora inclui salas ou pavimento de escritórios ou consultórios. Auditórios, garagens e restaurantes complementares ficam em Componente de população. Ao escolher um componente fora do escopo convencional, decida explicitamente se sua população entra no estudo principal, terá estudo separado ou será apenas registrada sem somar. Inclusão em uso composto é uma premissa do gestor; confira os critérios de demanda aplicáveis. Informe área, quantidade ou assentos conforme o componente.</p><ul><li>Indicação do ambiente: nome da sala ou uso, sem substituir o andar.</li><li>Posição da composição: ordem interna, única, com até 2 caracteres.</li><li>Andar servido: marcação real; vários ambientes podem atender ao mesmo andar.</li><li>Nível físico: necessário para marcações com letras, para ordenar e relacionar pavimentos.</li></ul><p>Copiar solicita a quantidade e permite o mesmo andar ou andares seguintes. Subir/Descer altera a ordem das composições. Ao mudar uma posição, só as posteriores são renumeradas. Confirme um único pavimento de acesso à rua; todos os ambientes desse andar serão desconsiderados.</p><p>Na parte inferior, confira a população calculada, informe a declaração do ambiente se houver e veja a adotada. O resumo reúne os ambientes por andar. A marcação com letras apresenta orientação de identificação de pavimentos conforme a referência de acessibilidade adotada.</p>`],
 ['premissas','5. Declare descontos e exclusões',`<p>Use os campos de desconto somente quando o ambiente satisfizer as condições e confirme os dados. Nos escritórios, o desconto de 50% permite até dois pavimentos distintos, imediatamente acima e imediatamente abaixo do acesso, até 5 m. Ambientes do mesmo andar podem compartilhar a condição. Nos demais usos permanece o limite de um andar. Conferir NBR 5665, 5.1.2. O flag Desconto populacional de 15% conserva a redução de área elegível prevista em 5.1.5; não aplica desconto irrestrito sobre declarações. O desconto escolar aparece em escolas. Para garagem ou restaurante, selecione uso exclusivo ou demanda externa. Para demanda externa e auditório, preencha os grupos e critérios do estudo separado na própria composição.</p><p>Registre em Como a população foi definida? a origem dos dados, contagens e justificativas. Consulte Premissas, Verificação de conteúdo e Explicação dos cálculos para conferir as regras aplicadas.</p>`],
 ['rede','6. Configure as escadas rolantes por trecho',`<p>No novo editor, os trechos são numerados para cima e para baixo do andar principal. Os nomes de origem/destino seguem a tabela de pavimentos. Pavimentos acima/abaixo do acesso não podem ultrapassar a quantidade cadastrada em cada ramo. Alterar a estrutura ou essas quantidades remodela os trechos, preservando as configurações vinculadas à mesma ligação física. Trechos retirados ficam arquivados no estudo para possível reutilização quando a ligação reaparece.</p><p>Cada trecho contém um ou mais conjuntos de escadas. A tabela apresenta parâmetros em linhas e colunas de Subida e Descida: quantidade de escadas similares, largura de degrau, velocidade e capacidade por escada quando a base for fabricante. Degraus disponíveis: 600, 800 e 1.000 mm. Adicionar escadas com outros parâmetros cria outro conjunto; Copiar replica um conjunto dentro do trecho e permite editar a cópia.</p><p>Inclinação aceita seleção de 0°, 10°, 12°, 30° e 35°, ou digitação manual. Zero corresponde a ligação horizontal e não pode justificar transporte entre pavimentos com desnível positivo. Essas opções não substituem a conferência técnica pelo fabricante e norma aplicável.</p><p>Capacidade por sentido soma capacidade unitária vezes quantidade em serviço. Depois converte para a janela de estudo e utilização declaradas. Subida e descida não são somadas como uma capacidade única. Exige-se par de mesma largura disponível, sentidos e quantidades cadastrados, além de capacidade suficiente em cada trecho dependente.</p><p>Se faltar sequenciamento até o andar principal, o trecho aparece em vermelho e sua população dependente fica no estudo dos elevadores. O relatório e PowerPoint mostram quantidades, degraus, velocidades, inclinações, capacidade acumulada e motivos de exclusão/manutenção da população. Alterar uma configuração exige recalcular o estudo.</p>`],
 ['grupos','7. Informe os elevadores',`<p>Em Parâmetros do estudo, organize até 20 grupos de elevadores de características iguais. Informe quantidade, lotação, paradas incluindo acesso e percurso entre extremos. Escolha a velocidade na tabela ou digite outro valor positivo.</p><p>Informe aceleração e jerk manualmente ou use os botões de ajuste de 0,05. Confira os alertas de percurso e conforto. Preencha tipo e abertura de porta, abertura/fechamento FAB, tempo por passageiro e tempo adicional por ciclo. Se disponível, registre o limite de partidas/h por elevador fornecido pelo fabricante; zero indica ausência dessa informação.</p><p>Em Curvas e tempos deste grupo, confira a prévia entre extremos, entre andares consecutivos e em percurso médio com paradas prováveis. Alterar velocidade, percurso, paradas, aceleração, jerk ou tempos atualiza a prévia. Calcular estudo completo disponibiliza os painéis de todos os grupos e inclui as curvas no relatório. O PPH de um percurso isolado tem hipótese própria; para a necessidade da população, consulte Partidas por hora.</p><p>Serviço comum permite uma análise consolidada. Zonas independentes precisam de população e critérios próprios; a soma conjunta fica informativa.</p>`],
 ['recalculo','8. Calcule e confira',`<p>Ao editar campos do estudo, a população é atualizada automaticamente quando os dados são válidos e os resultados anteriores são retirados. Na tela Cálculo de tráfego, clique em Calcular estudo completo: o sistema calcula primeiro a população e depois todos os estudos e relatórios.</p><p>Corrija os erros apresentados. Confira capacidade em 5 min, intervalo, mínimo estimado, comparação NBR/FAB, partidas necessárias/máximas, estudos separados e memória. Um alerta de dado precisa de revisão mesmo quando o cálculo é permitido.</p><p>Impressão, download do relatório, compartilhamento e gravação de cenário calculado exigem o cálculo completo atualizado.</p>`],
 ['atendimento','8.1. Informe o atendimento medido',`<p>Em Operação ou Performance de atendimento, escolha Leve, Moderado ou Modelo real. Para usar a tabela enviada, confirme sua unidade: percentual da população ou pessoas estimadas por bloco. Perfis antigos permanecem identificados como legados.</p><p>No modelo real, informe horários, data, responsável e observações. Preencha as quatro contagens por bloco de cinco minutos, inclusive zero. Vazio exige preenchimento. Amplie a janela quando necessário ou cole CSV com cabeçalho entrada;almoco_entrada;almoco_saida;saida. Confira os gráficos de entrada, almoço, saída e filas após o cálculo completo.</p><p>No almoço, os dois sentidos compartilham a capacidade. Medições não alteram a população calculada. Se houver fila ou pico acima da oferta, compare novos cenários de quantidade e tempos.</p>`],
 ['consumo','8.2. Configure a comparação energética',`<p>Escolha referência, base das partidas, horas energizadas, dias anuais e tarifa opcional. Partidas diárias declaradas abre um campo numérico por elevador. Na base PPH, usa-se PPH necessário × horas × utilização média do pico. Com expediente ativo, as horas são o intervalo início/fim; desativado, são as horas energizadas declaradas. A utilização percentual permanece registrada nos parâmetros. Abra cada tecnologia e substitua os exemplos por potência média, espera, recuperação e fonte documentada. Abra também Dados do fornecedor por grupo para informar cabos/cintas, polia e motores. Preencha somente as tecnologias ativadas; os outros grupos preservam suas premissas comuns. Informe tempo específico de movimento se conhecido, em especial para AC2 ou máquinas antigas.</p><p>Não deduza recuperação duas vezes: potência já líquida exige abatimento zero. O motor-gerador em espera deve ser incluído. Auxiliares são adicionados somente quando não estiverem nas demais potências. Confira redução negativa, referência zero e benefícios/limitações no relatório.</p>`],
 ['apresentacao','8.3. Gere a apresentação editável',`<p>Depois do cálculo completo, clique em Gerar PowerPoint editável. O PPTX reúne identificação, resultados, todos os gráficos, premissas e tecnologias. Os gráficos possuem planilhas incorporadas e podem ser alterados no PowerPoint. Modificações feitas no arquivo não atualizam automaticamente o sistema.</p><p>O relatório também inclui todos os gráficos do estudo, inclusive percurso médio e estudos separados. Para atualizar qualquer saída, altere o projeto e calcule novamente. Compartilhamentos históricos mantêm o cálculo original.</p>`],
 ['cenarios','9. Compare e guarde cenários',`<p>Depois de calcular, salve o cenário com um nome que explique a alternativa. Mude os parâmetros, calcule novamente e salve outro. Em Cenários, selecione as alternativas e compare os indicadores. A demonstração tem limites conforme o plano selecionado; não cobra valores.</p><p>Cenários ficam neste navegador e nesta conta local. Projetos são salvos na conta do programa. Exporte JSON para uma cópia transferível; a importação abre um estudo independente e recalcula com o motor atual. Guarde também as premissas de cada alternativa.</p>`],
 ['relatorio','10. Personalize e gere o relatório',`<p>Em Minha empresa, envie a logomarca em PNG, JPEG ou WebP, até 600 KB. Escolha cabeçalho ou rodapé para a marca e os contatos da empresa e salve. A marca também aparece no cabeçalho do sistema.</p><p>Após o cálculo completo, escolha Imprimir / Salvar PDF e use Salvar como PDF no diálogo do navegador. Baixar relatório HTML gera um arquivo independente com o estudo e a personalização. Revise a paginação na impressão. O final contém o formulário de tráfego conforme o modelo do Anexo A da NBR 5665 adotada.</p>`],
 ['compartilhar','11. Compartilhe uma versão para consulta',`<p>Com o projeto calculado e salvo, clique em Compartilhar estudo, defina validade se desejar e gere o link. O link guarda uma versão imutável com campos, resultados e relatório. Alterar o estudo posteriormente não modifica aquele link; gere outro para uma nova versão. É possível revogar links.</p><p>O convidado consulta e pode gerar/baixar seu relatório sem editar. Nesta etapa a hospedagem continua privada, restrita ao proprietário: acesso de clientes ou equipe depende de liberação privada aprovada. Cadastrar uma conta ou gerar um link não amplia a visibilidade e não envia convites.</p>`],
 ['equipe','12. Administração e equipe',`<p>Em Equipe e acessos, o administrador cadastra integrantes e pode clicar em Atualizar dados de cada conta para alterar nome, contatos e perfil. Contas já vinculadas mantêm o email de login. O proprietário mantém sua administração e um administrador não pode retirar o próprio perfil administrativo por esta tela.</p><p>Usuários comuns veem seus registros; administradores veem todos. Delegações concedem consulta ou edição da carteira de outro usuário, com prazo ou até revogação. Desativar uma conta bloqueia seu acesso ao programa. Baixar clientes e estudos é uma ação administrativa.</p>`],
 ['normas','13. Referências e cuidados com os dados',`<p>Para escadas rolantes, o programa cita ABNT NBR 16734-1:2022 e Parte 2:2023 para equipamentos existentes. A norma antiga fornecida foi desconsiderada da base ativa. Capacidades utilizadas provêm da tabela enviada pelo proprietário ou de dados documentados do fabricante; itens numéricos da edição atual aguardam validação no texto oficial. Adquira as normas pelo Catálogo ABNT.</p><p>Links históricos preservam a versão gerada. Reabra e recalcule o projeto para aplicar o motor atual. Para erros de salvamento, confira a mensagem, preserve o rascunho/exportação e reabra a última versão salva. A assinatura é demonstrativa, sem cobrança real.</p>`]
];
MANUAL_SECTIONS.unshift(['silsec10','SilSec · fornecedores, contratos e novos acessos',`<p>A atualização inclui vínculo da abertura da porta, alertas de altura, cópia dimensional, cadastro fiscal com aprovação, catálogo por fornecedor, pontuação comparativa e contratos. A origem dos dados deve ser documentada. Valores ausentes ficam pendentes; propostas podem ser enviadas incompletas.</p><p><a href="/silsec-especificacao.html">Especificação para revisar e usar em outros chats</a> · <a href="/silsec-comercializacao.html">Como preparar a comercialização</a> · <a href="/identidade-silsec.html">Identidade visual aprovada</a></p><p>Em Minha empresa consulte a organização e delegue acessos; em Fornecedores selecione a proposta, documentos, condições comerciais e convites. O fornecedor consulta somente sua proposta e pontos anônimos dos concorrentes. O cliente consulta os fornecedores autorizados de seu projeto.</p><p>A IA contratual depende da configuração de chave e modelo no servidor. Os pontos extraídos são uma triagem para revisão humana, não um parecer jurídico. A hospedagem continua privada e a cobrança permanece desativada.</p>`]);
export function guideSections(sections){return `<nav class="help-toc" aria-label="Índice">${sections.map(([id,title])=>`<a href="#help-${id}">${esc(title)}</a>`).join('')}</nav>${sections.map(([id,title,html])=>`<section class="card card-body below help-section" id="help-${id}"><h2>${esc(title)}</h2>${html}</section>`).join('')}`;}
export function helpPage(mode='manual',model){const calc=mode==='calculations',title=calc?'Explicação dos cálculos':'Manual do usuário';return `<div class="page-head"><div><h1>${title}</h1><p class="subtitle">Versão ${HELP_VERSION} · leitura passo a passo para conferir o estudo.</p></div><a class="btn" href="/${calc?'explicacao-dos-calculos':'manual-do-usuario'}.html" target="_blank" rel="noreferrer">Abrir versão para leitura e impressão</a></div>${guideSections(calc?(model?CALC_SECTIONS.filter(([id])=>['unidades91','modelos','curvas','performance','energia','tracao','pptx','fornecedores','expediente','pavimentos-zonas','entrada8','dimensoes','destino82','acesso83'].includes(id)||(model==='iso8100'?id.startsWith('iso-'):!id.startsWith('iso-'))):CALC_SECTIONS):MANUAL_SECTIONS)}`;}
export function calculationExplanation(model='nbr5665'){return `<div class="calculation-explanation"><h2>Explicação dos cálculos</h2>${CALC_SECTIONS.filter(([id])=>['unidades91','modelos','curvas','performance','energia','tracao','pptx','fornecedores','expediente','pavimentos-zonas','entrada8','dimensoes','destino82','acesso83'].includes(id)||(model==='iso8100'?id.startsWith('iso-'):!id.startsWith('iso-'))).map(([id,title,html])=>`<details class="reference-section"><summary>${esc(title)}</summary>${html}</details>`).join('')}</div>`;}
